import * as SQLite from 'expo-sqlite';
import type { Article, ArticleMeta, Section, SeedData } from './types';

// Bundled seed snapshot (generated by scripts/extract-data.mjs from the live site).
// First launch seeds SQLite from it so the app works fully offline before any sync.
const seedData = require('../../assets/seed-data/seed.json') as SeedData;

const db = SQLite.openDatabaseSync('collect.db');

export function initDb(): { seeded: boolean; count: number } {
  db.execSync(`
    CREATE TABLE IF NOT EXISTS articles (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      author TEXT NOT NULL,
      handle TEXT,
      platform TEXT NOT NULL,
      pname TEXT NOT NULL,
      date TEXT NOT NULL,
      mins INTEGER NOT NULL,
      cover TEXT NOT NULL,
      cover_alt TEXT NOT NULL DEFAULT '',
      summary TEXT NOT NULL DEFAULT '',
      keywords TEXT NOT NULL DEFAULT '[]',
      url TEXT NOT NULL DEFAULT '',
      stats TEXT,
      source_note TEXT NOT NULL DEFAULT '',
      related_json TEXT NOT NULL DEFAULT '[]',
      related_note TEXT,
      rev TEXT NOT NULL,
      sections_json TEXT,
      updated_at TEXT NOT NULL DEFAULT ''
    );
    CREATE TABLE IF NOT EXISTS user_state (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );
    CREATE TABLE IF NOT EXISTS meta (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS idx_articles_date ON articles(date DESC);
    CREATE INDEX IF NOT EXISTS idx_articles_platform ON articles(platform);
  `);
  const row = db.getFirstSync<{ c: number }>('SELECT COUNT(*) AS c FROM articles');
  const count = row?.c ?? 0;
  if (count === 0 && seedData.articles.length > 0) {
    db.withTransactionSync(() => {
      for (const a of seedData.articles) upsertArticle(a);
    });
    setMeta('seeded_from', seedData.updated_at);
    return { seeded: true, count: seedData.articles.length };
  }
  return { seeded: false, count };
}

function rowToMeta(r: Record<string, unknown>): ArticleMeta {
  return {
    id: r.id as string,
    title: r.title as string,
    author: r.author as string,
    handle: (r.handle as string | null) ?? null,
    platform: r.platform as string,
    pname: r.pname as string,
    date: r.date as string,
    mins: r.mins as number,
    cover: r.cover as string,
    coverAlt: (r.cover_alt as string) ?? '',
    summary: (r.summary as string) ?? '',
    keywords: safeJson<string[]>((r.keywords as string) || '[]', []),
    url: (r.url as string) ?? '',
    stats: (r.stats as string | null) ?? null,
    sourceNote: (r.source_note as string) ?? '',
    related: safeJson<string[]>((r.related_json as string) || '[]', []),
    relatedNote: (r.related_note as string | null) ?? null,
    rev: r.rev as string,
  };
}

function safeJson<T>(raw: string, fallback: T): T {
  try {
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

export function upsertArticle(a: Article | (ArticleMeta & { sections?: Section[] })): void {
  db.runSync(
    `INSERT INTO articles
      (id,title,author,handle,platform,pname,date,mins,cover,cover_alt,summary,keywords,url,stats,source_note,related_json,related_note,rev,sections_json,updated_at)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
     ON CONFLICT(id) DO UPDATE SET
      title=excluded.title, author=excluded.author, handle=excluded.handle,
      platform=excluded.platform, pname=excluded.pname, date=excluded.date,
      mins=excluded.mins, cover=excluded.cover, cover_alt=excluded.cover_alt,
      summary=excluded.summary, keywords=excluded.keywords, url=excluded.url,
      stats=excluded.stats, source_note=excluded.source_note,
      related_json=excluded.related_json, related_note=excluded.related_note,
      rev=excluded.rev,
      sections_json=COALESCE(excluded.sections_json, articles.sections_json),
      updated_at=excluded.updated_at`,
    [
      a.id, a.title, a.author, a.handle, a.platform, a.pname, a.date, a.mins,
      a.cover, a.coverAlt, a.summary, JSON.stringify(a.keywords), a.url,
      a.stats, a.sourceNote, JSON.stringify(a.related), a.relatedNote, a.rev,
      'sections' in a && a.sections ? JSON.stringify(a.sections) : null,
      new Date().toISOString(),
    ],
  );
}

const META_COLS =
  'id,title,author,handle,platform,pname,date,mins,cover,cover_alt,summary,keywords,url,stats,source_note,related_json,related_note,rev';

export function listArticles(opts?: { platform?: string; query?: string }): ArticleMeta[] {
  const where: string[] = [];
  const params: (string | number)[] = [];
  if (opts?.platform && opts.platform !== 'all') {
    where.push('platform = ?');
    params.push(opts.platform);
  }
  if (opts?.query) {
    const q = `%${opts.query.trim()}%`;
    where.push('(title LIKE ? OR author LIKE ? OR summary LIKE ? OR keywords LIKE ?)');
    params.push(q, q, q, q);
  }
  const sql = `SELECT ${META_COLS} FROM articles ${where.length ? `WHERE ${where.join(' AND ')}` : ''} ORDER BY date DESC, id DESC`;
  return db.getAllSync<Record<string, unknown>>(sql, params).map(rowToMeta);
}

export function getArticle(id: string): Article | null {
  const r = db.getFirstSync<Record<string, unknown>>(
    `SELECT ${META_COLS}, sections_json FROM articles WHERE id = ?`,
    [id],
  );
  if (!r) return null;
  const meta = rowToMeta(r);
  const sections = safeJson<Section[]>((r.sections_json as string) || '', []);
  return { ...meta, sections };
}

export function getArticleMeta(id: string): ArticleMeta | null {
  const r = db.getFirstSync<Record<string, unknown>>(
    `SELECT ${META_COLS} FROM articles WHERE id = ?`,
    [id],
  );
  return r ? rowToMeta(r) : null;
}

export function countArticles(): number {
  return db.getFirstSync<{ c: number }>('SELECT COUNT(*) AS c FROM articles')?.c ?? 0;
}

export function getArticlesUpdatedAt(): string | null {
  return getMeta('list_updated_at');
}

// ---------- user state (favorites / read / history / search / recommend) ----------
function getState(key: string): string | null {
  return db.getFirstSync<{ value: string }>('SELECT value FROM user_state WHERE key = ?', [key])?.value ?? null;
}
function setState(key: string, value: string): void {
  db.runSync('INSERT INTO user_state(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', [key, value]);
}

export function isFavorite(id: string): boolean {
  return getState(`fav:${id}`) === '1';
}
export function toggleFavorite(id: string): boolean {
  const next = !isFavorite(id);
  setState(`fav:${id}`, next ? '1' : '0');
  return next;
}
export function listFavorites(): ArticleMeta[] {
  const rows = db.getAllSync<{ key: string }>("SELECT key FROM user_state WHERE key LIKE 'fav:%' AND value='1'");
  const ids = rows.map((r) => r.key.slice(4));
  if (!ids.length) return [];
  const placeholders = ids.map(() => '?').join(',');
  return db
    .getAllSync<Record<string, unknown>>(
      `SELECT ${META_COLS} FROM articles WHERE id IN (${placeholders}) ORDER BY date DESC`,
      ids,
    )
    .map(rowToMeta);
}

export function markRead(id: string): void {
  setState(`read:${id}`, new Date().toISOString());
  const hist = getHistoryIds().filter((x) => x !== id);
  hist.unshift(id);
  setState('history', JSON.stringify(hist.slice(0, 200)));
}
export function isRead(id: string): boolean {
  return getState(`read:${id}`) !== null;
}
export function getReadMap(): Set<string> {
  const rows = db.getAllSync<{ key: string }>("SELECT key FROM user_state WHERE key LIKE 'read:%'");
  return new Set(rows.map((r) => r.key.slice(5)));
}
function getHistoryIds(): string[] {
  return safeJson<string[]>(getState('history') || '[]', []);
}
export function listHistory(): ArticleMeta[] {
  const ids = getHistoryIds();
  if (!ids.length) return [];
  const placeholders = ids.map(() => '?').join(',');
  const metas = db
    .getAllSync<Record<string, unknown>>(`SELECT ${META_COLS} FROM articles WHERE id IN (${placeholders})`, ids)
    .map(rowToMeta);
  const byId = new Map(metas.map((m) => [m.id, m]));
  return ids.map((id) => byId.get(id)).filter((m): m is ArticleMeta => !!m);
}
export function clearHistory(): void {
  db.runSync("DELETE FROM user_state WHERE key LIKE 'read:%' OR key = 'history'");
}

export function getSearchHistory(): string[] {
  return safeJson<string[]>(getState('search_history') || '[]', []);
}
export function addSearchHistory(q: string): void {
  const query = q.trim();
  if (!query) return;
  const hist = getSearchHistory().filter((x) => x !== query);
  hist.unshift(query);
  setState('search_history', JSON.stringify(hist.slice(0, 20)));
}

export interface RecommendItem {
  url: string;
  note: string;
  ts: number;
}
export function getRecommendList(): RecommendItem[] {
  return safeJson<RecommendItem[]>(getState('recommend') || '[]', []);
}
export function addRecommend(url: string, note: string): void {
  const list = getRecommendList();
  list.unshift({ url: url.trim(), note: note.trim(), ts: Date.now() });
  setState('recommend', JSON.stringify(list));
}
export function removeRecommend(ts: number): void {
  setState('recommend', JSON.stringify(getRecommendList().filter((x) => x.ts !== ts)));
}

// ---------- sync meta ----------
export function getMeta(key: string): string | null {
  return db.getFirstSync<{ value: string }>('SELECT value FROM meta WHERE key = ?', [key])?.value ?? null;
}
export function setMeta(key: string, value: string): void {
  db.runSync('INSERT INTO meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', [key, value]);
}
